using System;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
namespace RebirthEntityStudio {
 public static class RebirthHeadOwnership {
  [Serializable] sealed class Data {public int version;public string sourceCommit,license,faceTemplateHash,bodyTemplateHash;public float[] headWeights,bodyWeights;}
  [Serializable] sealed class Quads {public string templateHash;public int[] faceSizes,faceIndices;}
  static Data data;static string revision;static BodyTemplate bodyTemplate;static Quads quads;static readonly Dictionary<string,float[]> cache=new Dictionary<string,float[]>();
  static void Read(){string path=AssetDatabase.FindAssets("HeadOwnership t:TextAsset").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/HeadOwnership.json",StringComparison.Ordinal));if(path==null)throw new FileNotFoundException("Install anatomical HeadOwnership.json for head/body assembly");string current=AssetDatabase.GetAssetDependencyHash(path).ToString();if(data!=null&&revision==current)return;data=JsonUtility.FromJson<Data>(AssetDatabase.LoadAssetAtPath<TextAsset>(path).text);if(data.version!=1||data.license!="CC0-1.0"||data.headWeights==null||data.bodyWeights==null||data.headWeights.Concat(data.bodyWeights).Any(v=>float.IsNaN(v)||float.IsInfinity(v)||v<0||v>1))throw new InvalidDataException("Unsupported anatomical ownership data");revision=current;cache.Clear();bodyTemplate=null;quads=null;}
  static float[] Refine(FaceTemplate layout,float[] weights,int level,string key){float[] result;if(cache.TryGetValue(key,out result))return result;if(level==0)result=(float[])weights.Clone();else{List<Vector3> points;List<Vector2> uv;List<int> triangles;RebirthFaceGeneratorModel.CatmullClark(layout,weights.Select(v=>new Vector3(v,0,0)).ToList(),Enumerable.Range(0,weights.Length).Select(i=>new Vector2(layout.uv[i*2],layout.uv[i*2+1])).ToList(),level,out points,out uv,out triangles);result=points.Select(v=>Mathf.Clamp01(v.x)).ToArray();}cache[key]=result;return result;}
  public static float[] Head(FaceTemplate template,int resolution,int vertexCount){Read();if(template.contentHash!=data.faceTemplateHash||template.sourceIds.Length!=data.headWeights.Length)throw new InvalidDataException("Head ownership does not match the accepted template");var skin=Refine(template,data.headWeights,resolution,"head:"+resolution);if(skin.Length>vertexCount)throw new InvalidDataException("Head ownership refinement differs from skin topology");var result=Enumerable.Repeat(1f,vertexCount).ToArray();Array.Copy(skin,result,skin.Length);return result;}
  public static float[] Body(int vertexCount){Read();if(bodyTemplate==null){bodyTemplate=RebirthBodyGeneratorModel.ReadTemplate();if(bodyTemplate.contentHash!=data.bodyTemplateHash)throw new InvalidDataException("Body ownership does not match the body template");}if(vertexCount==data.bodyWeights.Length)return (float[])data.bodyWeights.Clone();if(quads==null){string path=AssetDatabase.FindAssets("BodyTopology t:TextAsset").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/BodyTopology.json",StringComparison.Ordinal));if(path==null)throw new FileNotFoundException("Install source body topology for refined neck ownership");quads=JsonUtility.FromJson<Quads>(AssetDatabase.LoadAssetAtPath<TextAsset>(path).text);if(quads.templateHash!=data.bodyTemplateHash)throw new InvalidDataException("Body ownership topology mismatch");}var layout=new FaceTemplate{sourceIds=bodyTemplate.sourceIds,uv=bodyTemplate.uv,faceSizes=quads.faceSizes,faceIndices=quads.faceIndices};for(int level=1;level<=2;level++){var weights=Refine(layout,data.bodyWeights,level,"body:"+level);if(weights.Length==vertexCount)return (float[])weights.Clone();}throw new InvalidDataException("Unsupported body topology for anatomical neck ownership");}
 }
}